  if (source instanceof Map) {
    return Array.from(source.entries());
  }

  if (Array.isArray(source)) {
    return source.map((entry) => [...entry]);
  }

  return Object.entries(source);
}

export class FrozenDict {
  #data;

  constructor(source = []) {
    this.#data = new Map(toEntries(source));
    Object.freeze(this);
  }

  get(key) {
    return this.#data.get(key);
  }

  entries() {
    return this.#data.entries();
  }

  [Symbol.iterator]() {
    return this.entries();
  }

  toPythonString() {
    return `FrozenDict(${pyReprMap(this.#data)})`;
  }

  toString() {
    return this.toPythonString();
  }
}

