import path from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  camel2under,
  under2camel,
  slugify,
  unit_len,
  cardinalize,
} from './lib/strutils/index.mjs';
import { FrozenDict } from './lib/dictutils/index.mjs';
import {
  ArgumentParserError,
  formatError,
  formatHelp,
  parseArgs,
} from './lib/cli/argparse.mjs';
import { pyPrint } from './lib/py/print.mjs';

function buildMap(entries) {
  const map = new Map();
  for (const [key, value] of entries) {
    map.set(key, value);
  }
  return map;
}

function runProgram(aValue) {
  const strings = aValue.split(',');

  const result1 = strings.map((value) => camel2under(value));
  pyPrint(result1);

  const result2 = strings.map((value) => under2camel(value));
  pyPrint(result2);

  const result3 = strings.map((value) => slugify(value));
  pyPrint(result3);

  const result4 = camel2under(strings[0]);
  pyPrint(result4);

  const result5 = under2camel(result4);
  pyPrint(result5);

  const result6 = slugify(strings[strings.length - 1]);
  pyPrint(result6);

  const result7 = unit_len(strings, 'string');
  pyPrint(result7);

  const result8 = cardinalize('string', strings.length);
  pyPrint(result8);

  const result9 = camel2under(strings.join(''));
  pyPrint(result9);

  const result10 = slugify(strings.join('_'));
  pyPrint(result10);

  const result11 = under2camel(result9.replace(/ /g, '_'));
  pyPrint(result11);

  const result12 = unit_len(strings.slice(0, 3), 'item');
  pyPrint(result12);

  const result13 = cardinalize('item', 1);
  pyPrint(result13);

  const result14 = camel2under('TestString');
  pyPrint(result14);

  const result15 = slugify('Test String!');
  pyPrint(result15);

  const mapping = buildMap(strings.map((key, index) => [key, result1[index]]));

  const result16 = new FrozenDict(mapping);
  pyPrint(result16);

  const result17 = new FrozenDict(buildMap(Array.from(mapping.entries(), ([key, value]) => [value, key])));
  pyPrint(result17);

  const result18 = new FrozenDict(buildMap(Array.from(mapping.entries(), ([key, value]) => [key, value.length])));
  pyPrint(result18);

  const result19 = new FrozenDict(buildMap(Array.from(mapping.entries(), ([key, value]) => [key.toUpperCase(), value])));
  pyPrint(result19);

  const result20 = new FrozenDict(buildMap(Array.from(mapping.entries(), ([key, value]) => [key, slugify(value)])));
  pyPrint(result20);
}

export function main(argv = process.argv) {
  try {
    const parsed = parseArgs(argv);

    if (parsed.kind === 'help') {
      process.stdout.write(formatHelp(parsed.programName));
      return 0;
    }

    runProgram(parsed.args.a);
    return 0;
  } catch (error) {
    if (error instanceof ArgumentParserError) {
      process.stderr.write(formatError(error.programName, error.message));
      return 2;
    }
    throw error;
  }
}

const entryPath = fileURLToPath(import.meta.url);
if (process.argv[1] && path.resolve(process.argv[1]) === entryPath) {
  process.exitCode = main(process.argv);
}

