      continue;
    }
    if (character === '\n') {
      body += '\\n';
      continue;
    }
    if (character === '\r') {
      body += '\\r';
      continue;
    }
    if (character === '\b') {
      body += '\\x08';
      continue;
    }
    if (character === '\f') {
      body += '\\x0c';
      continue;
    }
    if (character === '\v') {
      body += '\\x0b';
      continue;
    }
    if (codePoint < 0x20 || codePoint === 0x7f) {
      body += formatCodePointEscape(codePoint);
      continue;
    }

    body += character;
  }

