}

export function pyReprMap(map) {
  const parts = [];
  for (const [key, value] of map.entries()) {
    parts.push(`${pyRepr(key)}: ${pyRepr(value)}`);
  }
  return `{${parts.join(', ')}}`;
}

export function pyRepr(value) {
  if (typeof value === 'string') {
    return reprString(value);
  }

  if (typeof value === 'number' || typeof value === 'bigint') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pyRepr(item)).join(', ')}]`;
  }

  if (value instanceof Map) {
    return pyReprMap(value);
  }

  if (value && typeof value.toPythonString === 'function') {
    return value.toPythonString();
  }

  throw new TypeError(`Unsupported value for Python repr: ${String(value)}`);
}

